// Limpia los textos y prepara el nombre de la foto, si vino una.
const TIPOS = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };
const delFormulario = $('Formulario de reportes').isExecuted;
const fecha = $now.setZone('America/La_Paz').toFormat('yyyy-MM-dd');

return $input.all().map((item, i) => {
  const r = item.json;
  const foto = item.binary?.foto;
  // Un campo de archivo vacío puede llegar como un archivo sin nombre o de 0 bytes: no cuenta como foto.
  const fotoValida = Boolean(foto && foto.fileName && TIPOS[foto.mimeType] && !/^0\s/.test(String(foto.fileSize ?? '')));
  const fotoRuta = fotoValida
    ? `${fecha}/reporte-${$execution.id}-${i}-${Math.random().toString(36).slice(2, 8)}.${TIPOS[foto.mimeType]}`
    : null;
  return {
    json: {
      descripcion: String(r.descripcion ?? '').trim().replace(/\s+/g, ' ').slice(0, 2000),
      lugar: String(r.lugar ?? '').trim().replace(/\s+/g, ' ').slice(0, 300),
      tiene_foto: fotoValida,
      foto_ruta: fotoRuta,
      origen: delFormulario ? 'formulario' : 'prueba',
    },
    // La foto sigue viaje en el binario «foto» nada más si es válida.
    ...(fotoValida ? { binary: { foto } } : {}),
  };
});

// Junta el reporte con lo que dijo la IA y deja valores que la tabla acepta.
const CATEGORIAS = ['basura', 'quema', 'agua', 'arboles', 'animales', 'ruido', 'otro'];
const URGENCIAS = ['alta', 'media', 'baja'];
const limpiar = (t) => String(t ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

return $input.all().map((item, i) => {
  const ia = item.json.output ?? {};
  // El ítem de «Preparar el reporte» que corresponde a este (con su foto, si tiene).
  const reporte = $('Preparar el reporte').itemMatching(i);
  const categoria = CATEGORIAS.includes(limpiar(ia.categoria)) ? limpiar(ia.categoria) : 'otro';
  const urgencia = URGENCIAS.includes(limpiar(ia.urgencia)) ? limpiar(ia.urgencia) : 'media';
  return {
    json: {
      ...reporte.json,
      categoria,
      urgencia,
      resumen: String(ia.resumen ?? '').trim().slice(0, 500),
    },
    ...(reporte.binary ? { binary: reporte.binary } : {}),
  };
});

